#include <stdbool.h>

/* ========================================================================== */
/* Interrupt Handlers                                                         */
/* ========================================================================== */
void LPUART0_SignalEvent(uint32_t event)
{
    (void)event;
}

void SysTick_Handler(void)
{
    TurnSignals_Tick();
}

/* ========================================================================== */
/* Application Functions                                                      */
/* ========================================================================== */
void InitHardware(void)
{
    BOARD_InitHardware();
    BOARD_InitDebugConsole();

    PRINTF("Autonomous Vehicle System Initialized!\r\n");

    /* Initialize Turn Signals (PWM submodules & Pins) */
    TurnSignals_InitHardware();

    /* Start 100ms Tick for the Blinker state machine */
    SysTick_Config(SystemCoreClock / 10U);
}

void ProcessUart(void)
{
    if (kLPUART_RxDataRegFullFlag & LPUART_GetStatusFlags((LPUART_Type *)BOARD_DEBUG_UART_BASEADDR))
    {
        uint8_t ch = LPUART_ReadByte((LPUART_Type *)BOARD_DEBUG_UART_BASEADDR);

        if (ch == 'l' || ch == 'L')
        {
            SignalLeft();
        }
        else if (ch == 'r' || ch == 'R')
        {
            SignalRight();
        }
        else if (ch == 'n' || ch == 'N')
        {
            SignalOff();
        }
    }
}

/* ========================================================================== */
/* Main function                                                              */
/* ========================================================================== */
int main(void)
{
    InitHardware();

    while (1)
    {
        ProcessUart();
        ProcessBlinker();
        ProcessBuzzer();
    }
}
