    /* PWM Configuration struct used for all X channels */
    pwm_signal_param_t pwmXConfig = {
        .pwmChannel = kPWM_PwmX,
        .dutyCyclePercent = 0U, 
        .level = kPWM_HighTrue,
        .faultState = kPWM_PwmFaultState0,
