    /* Start Timers and Load logic for all Submodules */
    PWM_SetPwmLdok(FLEXPWM0_PERIPHERAL, (1U << FLEXPWM0_SM0) | (1U << FLEXPWM0_SM1) | (1U << FLEXPWM0_SM2), true);
